<template>
    <div class="row justify-end q-pr-lg q-gutter-sm">
        <f-btn
            :label="$t('send_test')"
            @click="sendTest"
        />
        <f-btn
            :label="$t('save')"
            @click="submitForm"
        />
    </div>

    <q-form @submit="submit" ref="editForm">
        <div class="row">
            <div class="col-3 q-pt-sm q-pl-lg">
                <div>
                    <q-input
                        outlined
                        dense
                        :label="$t('name')"
                        v-model="email_template_data.name"
                        lazy-rules
                        :rules="[
                            (val: string) => (val && val.length > 0) || $t('please_input_name'),
                            (val: string) => (!val || val.length <= maxFieldLength) || $t('EMAIL_TEMPLATE_NAME_TOO_LONG')
                        ]"
                        class="white-inputs"
                    >
                    </q-input>
                </div>
                <div class="q-pb-lg">
                    <q-select
                        :label="$t('document_type')"
                        map-options
                        dense
                        outlined
                        v-model="email_template_data.doc_type" 
                        :options="active_doc_types_sub_types_list"
                        emit-value
                        :disable="true"
                        class="white-inputs"
                    >
                    </q-select>
                </div>
                <div>
                  <f-toggle size="xs"
                      v-model="email_template_data.include_document_as_attachment"
                      :label="$t('include_document_as_attachment')"
                  />
                </div>
            </div>
            <div class="col-9 q-pt-sm q-pl-lg q-pr-lg" ref="editorContainer" style="height: calc(100vh - 200px);">
                <div class='q-mb-md' style="position: relative;">
                  <q-editor
                      v-model='email_template_data.subject'
                      ref='subjectEditorRef'
                      :toolbar="[]"
                      :min-height="'40px'"
                      :max-height="'40px'"
                      :placeholder="$t('subject')"
                      @keydown.enter.prevent
                      @keydown.shift.enter.prevent
                      @paste='handlePaste'
                      @input='stripHtml'
                      class='single-line-editor'
                  />
                    <span class="editor-plus-btn" @click="showSubjectMenu" :style="{ '--org-color': user_settings['ORG_COLOR_PREFERENCE'] }">
                        <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 22 22">
                            <circle cx="11" cy="11" r="11" fill="var(--org-color)"/>
                            <line x1="11" y1="6.1" x2="11" y2="15.9" stroke="#fff" stroke-linecap="round" stroke-width="3"/>
                            <line x1="6.1" y1="11" x2="15.9" y2="11" stroke="#fff" stroke-linecap="round" stroke-width="3"/>
                        </svg>
                    </span>
                    <Properties
                        :filteredDataKey="filteredDataKey"
                        :editorRef="subjectEditorRef"
                        popupType="subject"
                        @update-inserted-keys="handleInsertedKeys"
                        v-if="showProperties"
                    />
                     
                </div>
                <div v-if="!view_source" class="editor-wrapper" style="position: relative;">
                    <q-editor
                        ref="editorRef"
                        :style="`min-height:28rem;height: ${editorHeight}px;max-height: ${editorHeight}px;`"
                        v-model="email_template_data.value"
                        :definitions="{
                            upload: {
                                tip: 'Upload to cloud',
                                icon: 'cloud_upload',
                                label: 'Upload',
                                handler: openFileDialog
                            },
                            viewsource: {
                                icon: 'code',
                                handler: openViewSource
                            }
                        }"
                        :toolbar="[
                            ['left', 'center', 'right', 'justify'],
                            ['quote', 'unordered', 'ordered', 'outdent', 'indent'],
                            ['viewsource'],
                            ['bold', 'italic', 'strike', 'underline'],
                            ['undo', 'redo'],
                            ['upload'],
                        ]"
                    />
                        <span class="editor-plus-btn-for-content" @click="showMessageMenu" :style="{ '--org-color': user_settings['ORG_COLOR_PREFERENCE'] }">
                            <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 22 22">
                                <circle cx="11" cy="11" r="11" fill="var(--org-color)"/>
                                <line x1="11" y1="6.1" x2="11" y2="15.9" stroke="#fff" stroke-linecap="round" stroke-width="3"/>
                                <line x1="6.1" y1="11" x2="15.9" y2="11" stroke="#fff" stroke-linecap="round" stroke-width="3"/>
                            </svg>
                        </span>
                    <Properties
                        :filteredDataKey="filteredDataKey"
                        :editorRef="editorRef"
                        popupType="message"
                        @update-inserted-keys="handleInsertedKeys"
                         v-if="showPropertiesForContent"
                    />
                    
                    <input
                        type="file"
                        ref="fileInput"
                        style="display: none"
                        @change="handleFileUpload"
                    />
                </div>
                <div v-else>
                    <q-icon 
                        name="code" 
                        style="font-size: 18px;" 
                        class="q-pb-sm cursor-pointer" 
                        @click="backToEditor"
                    >
                    </q-icon>
                    <q-icon 
                        name="edit_note" 
                        class="format-icon cursor-pointer q-pb-sm" 
                        @click="formatCode"
                    >
                        <q-tooltip>{{ $t('format_button') }}</q-tooltip>
                    </q-icon>
                    <Editor 
                        :editorValue="email_template_data.value" 
                        :formatCode="is_format_code"
                        @updated-value="updateValue" 
                        @formatComplete="afterFormatted"
                    />
                </div>

            </div>
        </div>
    </q-form>

  <q-dialog v-model="send_test_dialog">
    <q-card>
      <q-form @submit="submitSendTest">
        <q-card-section>
          <div class="row">
            <div style="width: 100%">
              <q-input
                outlined
                dense
                :label="$t('receiver_email')"
                v-model="receiver_email"
                :rules="[
                  (val: string) =>
                    (val && val.length > 0) || $t('please_input_email'),
                  (val: string) => isValidEmail(val) || $t('invalid_email'),
                ]"
              >
              </q-input>
            </div>
          </div>
          <div class="properties" v-if="insertedFields.length">
            <div
              v-for="(data, index) in insertedFields"
              :key="index"
              :class="index ? 'properties-child' : ''"
            >
              <q-input
                outlined
                dense
                :label="data.name"
                v-model="filteredDataValues[data.key]"
              >
                <template v-slot:append>
                  <q-icon
                    name="content_copy"
                    style="font-size: 16px"
                    class="cursor-pointer"
                    @click="clickToCopyKey(data.key)"
                  >
                    <q-tooltip>{{ $t('click_to_copy_key') }}</q-tooltip>
                  </q-icon>
                </template>
              </q-input>
            </div>
          </div>
        </q-card-section>

        <q-card-actions align="right">
          <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
          <f-btn
            class="q-mr-sm"
            data-cy="setvatfield"
            :label="$t('send')"
            type="submit"
          />
        </q-card-actions>
      </q-form>
    </q-card>
  </q-dialog>

  <q-inner-loading :showing="loading" style="z-index: 2">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { emailTemplateFieldMaxLength } from 'src/constants';
import { handleSubjectPaste, toPlainText } from 'src/pages/Settings/EmailTemplate/subject-field';
    import { defineComponent, ref } from 'vue';
    import { emailTemplateStore, useDocTypeFieldsStore, useDropdownStore, useSettingStore } from 'src/store/main';
    import { storeToRefs } from 'pinia';
    import { ApiExceptions } from 'src/exceptions';
    import { useTranslate } from '@tolgee/vue';
    import type { dynamicObj } from 'src/pages/assets'
    import { copyToClipboard } from 'quasar';
    import Editor from 'src/pages/Settings/SupplierEmailTemplate/Editor.vue';
    import Properties from 'src/pages/Settings/Components/EmailTemplate/Properties.vue';
    export default defineComponent ({
                components: {
            Editor,
            Properties
        },
        beforeCreate() {
          this.resetEmailTemplateStore();
        },
        mounted() {
            this.init();
            this.setEditorHeight();
            window.addEventListener('resize', this.setEditorHeight);
            document.addEventListener('click', this.handleClickOutside);
        },
        unmounted() {
            window.removeEventListener('resize', this.setEditorHeight);
            document.removeEventListener('click', this.handleClickOutside);
        },
        watch: {
            sample_data: {
                handler: function (newVal, oldVal) {
                    if (oldVal != newVal) {
                        this.addAppUrlVariable();
                    }
                },
            },
        },
        methods: {
            setEditorHeight() {
                this.$nextTick(function () {
                    const container = this.$refs.editorContainer as HTMLElement;
                    if (container) {
                        const parentHeight = container.getBoundingClientRect().height;
                        this.editorHeight = parentHeight;
                    }
                })
            },
            formatCode() {
                this.is_format_code = true;
            },
            afterFormatted(value: any) {
                this.is_format_code = value;
            },
            isValidEmail(email: string) {
                const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
                return re.test(email);
            },
            updateValue(value: string) {
                this.email_template_data.value = value;
            },
            openViewSource() {
                this.view_source = true;
            },
            backToEditor() {
                this.view_source = false;
            },
            async init() {
                try {
                    this.loading = true;
                    await this.prepareDocTypeAndSubTypesList();
                    await this.getAllDocTypeFields();
                    await this.getEmailTemplate();
                    this.showVariableDocumentFields();
                    await this.getSampleData();
                    //Parse template and get variables.
                    this.getVariablesFromTemplate(this.email_template_data.subject)
                    this.getVariablesFromTemplate(this.email_template_data.value)
                } catch (error) {
                    logError(error);
                } finally {
                    this.loading = false;
                }
            },
            async getEmailTemplate() {
                try {
                  this.email_template_id = this.$route.params.id as string;
                  if (this.email_template_id) {
                      await this.getOneEmailTemplate(this.email_template_id);
                  }
                } catch (err: any) {
                  const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
                  notify.error(msg);
                  logError(err);
                } finally {
                  if (!this.email_template_data?.id) {
                    this.$router.push('/settings/email-templates');
                  }
                }
            },
            showVariableDocumentFields() {
              if (this.email_template_data.doc_type) {
                const selectedDocumentType = this.active_doc_types_sub_types_list.find((item: any) =>
                    item.value === this.email_template_data.doc_type
                );
                if (!selectedDocumentType) {
                  return;
                }
                let doc_type = selectedDocumentType['value'];
                if (selectedDocumentType['doc_type_key'] != undefined) {
                  doc_type = selectedDocumentType['doc_type_key']
                }
                this.filteredDataKey = this.getFieldsArrayByDocType(doc_type);
              } else {
                this.filteredDataKey = [];
              }
              
            },
            submitForm() {
                const form = this.$refs.editForm as any;
                form.submit()
            },
            async submit() {
                try {
                    // Normalise first so the value validated here is exactly the
                    // value posted to the backend.
                    this.stripHtml();
                    const subject = this.email_template_data.subject;
                    if (!subject.trim()) {
                        notify.error(this.$t('please_input_subject'));
                        return;
                    }
                    // QEditor takes no validation rules, so the subject limit is
                    // enforced here instead of by the form.
                    if (subject.length > this.maxFieldLength) {
                        notify.error(this.$t('EMAIL_TEMPLATE_SUBJECT_TOO_LONG'));
                        return;
                    }
                    if (!this.email_template_data.value.trim()) {
                        notify.error(this.$t('email_content_empty'));
                        return;
                    } else {
                        this.loading = true;
                        const response = await this.updateEmailTemplate(this.email_template_id, this.email_template_data);
                        if (!response || response.success === false) {
                            throw response;
                        }
                        await this.getEmailTemplate();
                        notify.success(this.$t('email_template_updated_success'));
                    }
                } catch (err: any) {
                    const msg = ApiExceptions.getErrorMessage(err);
                    notify.error(msg);
                    logError(err);
                } finally {
                    this.loading = false;
                }
            },
            sendTest() {
                this.send_test_dialog = true;
            },
            async submitSendTest() {
                try {
                    this.send_test_dialog = false;
                    this.loading = true;
                    this.prepareDataSend = {
                        receiver_email: this.receiver_email,
                        subject: this.email_template_data.subject,
                        include_document_as_attachment: this.email_template_data.include_document_as_attachment,
                        body: this.email_template_data.value,
                        data: {...this.filteredDataValues}
                    }

                    await this.sendTestEmail(this.prepareDataSend);
                    this.resetSendEmailData();
                    notify.success(this.$t('email_sent_successfully'));
                } catch (err: any) {
                    const msg = ApiExceptions.getErrorMessage(err);
                    notify.error(msg);
                } finally {
                    this.loading = false;
                }
            },
            openFileDialog() {
                const fileInput = this.$refs.fileInput as HTMLInputElement;
                fileInput.click();
            },
            async handleFileUpload(event: Event) {
                const target = event.target as HTMLInputElement;
                const file = target.files?.[0];
                if (file) {
                    await this.onUploadFile(file);
                    if (file.type.startsWith('image/')) {
                        this.insertImageToEditor(this.stream_file_data);
                    } else {
                        this.insertFileLinkToEditor(this.stream_file_data, file.name);
                    }
                }
            },
            insertImageToEditor(imageUrl: string) {
                this.email_template_data.value += `<img src="${imageUrl}" alt="Uploaded Image" />`;
            },
            insertFileLinkToEditor(fileUrl: string, fileName: string) {                
                const linkHtml = `<a class="cursor-pointer" href="${fileUrl}" target="_blank">${fileName}</a>`;
                this.email_template_data.value += linkHtml;
            },
            selectEmailChange(value: string) {
                this.email_template_data.email_type = value;
            },
            resetSendEmailData() {
                this.receiver_email = '';
                this.filteredDataValues = [];
            },
            async clickToCopyKey(key: string) {
                const key_copy = `{{${key}}}`;
                await copyToClipboard(key_copy);
                notify.success(this.$t('copy_key_successfully'));
            },
            plainSubject () {
                return toPlainText(this.email_template_data.subject)
            },
            stripHtml () {
                this.email_template_data.subject = this.plainSubject()
            },
            handlePaste (evt: ClipboardEvent) {
                handleSubjectPaste(evt)
            },
            addAppUrlVariable() {
                const filteredType = this.sample_data.filter((supplier_type: any) => {
                    return supplier_type.email_type == 'supplier_approve';
                });
                
                const appUrlVariable = filteredType[0]?.data_key?.[0];
                if (!appUrlVariable) {
                    return;
                }

                const { placeholder, ...cleaned } = appUrlVariable;
                this.filteredDataKey.push(cleaned)
            },

            handleInsertedKeys(key: string, name: string) {
                if ( !this.insertedFields.find(item =>item.key == key)) {
                    this.insertedFields.push({ 'key': key, 'name' : name});
                }
            },
                 
            getVariablesFromTemplate(content: string) {
                // Match everything inside {{ ... }}
                const regex = /{{(.*?)}}/g;
                
                const keys = Array.from(content.matchAll(regex), m => m[1]);
                this.insertedFields = this.filteredDataKey.filter(item => keys.includes(item.key));
            },
            showSubjectMenu() {
                this.showProperties = !this.showProperties;
            },
            showMessageMenu() {
                this.showPropertiesForContent = !this.showPropertiesForContent;
            },
            handleClickOutside(event: { target: any; }) {
                const menus = document.querySelectorAll('.floating-menu'); 
                let clickInsideAnyMenu = false;

                menus.forEach(menu => {
                    if (menu.contains(event.target)) {
                        clickInsideAnyMenu = true;
                    }
                });

                // Close the menu only if click is outside all menus
                if (!clickInsideAnyMenu && !['line','svg','circle'].includes(event.target.tagName.toLowerCase())) {
                    this.showProperties = false; // or close all menus if needed
                    this.showPropertiesForContent = false;
                }
            }
        },
        data() {
            return {
                files: ref(null),
                email_template_id: ref(''),
                receiver_email: ref(''),
                filteredDataKey: ref<{ index: number; key: string; name: string; }[]>([]),
                filteredDataValues: ref<{ key: string; name?: string }[]>([]),
                prepareDataSend: {},
                view_source: ref(false),
                is_format_code: ref(false),
                editorHeight: 0,
                insertedFields: [] as { key: string, name: string }[],
                showProperties : false,
                showPropertiesForContent : false
            }
        },
        setup() {
            const dropdown_store = useDropdownStore();
            const subjectEditorRef = ref(null) as any;
            const { active_doc_types_sub_types_list } = storeToRefs(dropdown_store);
            const { prepareDocTypeAndSubTypesList } = dropdown_store;
            const doc_type_fields_store = useDocTypeFieldsStore();
            const { getFieldsArrayByDocType } = storeToRefs(doc_type_fields_store);
            const { getAllDocTypeFields } = doc_type_fields_store;

            const email_template = emailTemplateStore();
            const editorRef = ref(null) as any;
            const { 
                loading, 
                email_template_data,
                send_test_dialog,
                stream_file_data,
                sample_data
            } = storeToRefs(email_template);
            const { 
                getOneEmailTemplate,
                updateEmailTemplate,
                onUploadFile,
                sendTestEmail,
                resetEmailTemplateStore,
                getSampleData
            } = email_template;

            const { t } = useTranslate();

            const settings_store = useSettingStore();
            const { user_settings } = storeToRefs(settings_store);
            
            return {
                t,
                onUploadFile,
                editorRef,
                subjectEditorRef,
                getOneEmailTemplate,
                updateEmailTemplate,
                sendTestEmail,
                email_template_data,
                loading,
                send_test_dialog,
                stream_file_data,
                resetEmailTemplateStore,
                getAllDocTypeFields,
                getFieldsArrayByDocType,
                prepareDocTypeAndSubTypesList,
                active_doc_types_sub_types_list,
                sample_data,
                getSampleData,
                user_settings,
                maxFieldLength: emailTemplateFieldMaxLength
            }
        },
       
    })
</script>

